<?php require_once __DIR__.'/config/config.php';$code=$_GET['order']??'';$s=$pdo->prepare('SELECT o.*,c.name,c.phone,c.email,c.address,c.city FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.order_code=?');$s->execute([$code]);$o=$s->fetch();if(!$o||($_SESSION['last_order']??'')!==$code)exit('Order confirmation is not available.');require 'includes/header.php';?><section class="section"><div class="container text-center"><div class="display-4 text-success">✓</div><h1 style="font-family:'Playfair Display'">Thank You for Your Order!</h1><p>Your order has been placed successfully.</p><div class="admin-card mx-auto text-start mt-4" style="max-width:600px"><h5>Order ID: <?=e($o['order_code'])?></h5><p><?=e($o['name'])?> · <?=e($o['phone'])?></p><p><?=e($o['address'])?>, <?=e($o['city'])?></p><h4 class="price"><?=money($o['total'])?></h4><span class="status"><?=e($o['status'])?></span></div><a class="btn btn-gold mt-4" href="track.php">Track Order</a></div></section><?php require 'includes/footer.php';?>